}

store pg [database postgresql]: Orders DB
api [go]: Orders API
frame k8s "Kubernetes cluster" [kubernetes] { ... }

frame dmz "DMZ, 10.0.1.0/24" [orange] {
  lb: Load balancer
}

frame region "eu-west-1" {
  frame vpc "VPC" {
    ...
  }
}

column "web servers" {
  w1: web-01
  w2: web-02
}

